<template><section class="flex h-full min-h-0 flex-col overflow-hidden bg-background"><header class="flex min-h-14 items-center gap-2 border-b px-4"><Button variant="ghost" size="sm" @click="router.push({name:'goal-detail',params:{id:goalId}})"><ArrowLeft class="mr-1 h-4 w-4"/>{{ t('common.back') }}</Button><h1 v-if="kr" class="font-semibold">{{ kr.title }}</h1></header><div v-if="kr" class="min-h-0 flex-1 overflow-auto p-4"><article class="mx-auto max-w-2xl rounded-lg border bg-card p-5"><div class="flex justify-between"><div><p class="text-sm text-muted-foreground">{{ kr.progress.aggregationMethod }}</p><p class="mt-1 text-2xl font-semibold">{{ kr.progress.currentValue }} / {{ kr.progress.targetValue }} {{ kr.progress.unit ?? '' }}</p></div><span class="text-xl font-semibold">{{ Math.round(kr.progressPercentage) }}%</span></div><Progress class="mt-4" :model-value="kr.progressPercentage"/><dl class="mt-5 grid gap-4 text-sm sm:grid-cols-2"><div><dt class="text-muted-foreground">Initial value</dt><dd>{{ kr.progress.initialValue }}</dd></div><div><dt class="text-muted-foreground">Target timeframe</dt><dd>{{ kr.target ? goalTimeframeLabel(kr.target, locale) : '—' }}</dd></div><div><dt class="text-muted-foreground">Weight</dt><dd>{{ kr.weight }}</dd></div><div><dt class="text-muted-foreground">Completed</dt><dd>{{ kr.isCompleted ? 'Yes' : 'No' }}</dd></div></dl><p v-if="kr.description" class="mt-5 text-sm text-muted-foreground">{{ kr.description }}</p></article></div></section></template>
<script setup lang="ts">import { computed,onMounted } from 'vue';import { useRoute,useRouter } from 'vue-router';import { useI18n } from 'vue-i18n';import { ArrowLeft } from '@lucide/vue';import { Button,Progress } from '@memoflow/ui-vue-shadcn';import { useGoal } from '../composables/useGoal';import { goalTimeframeLabel } from '@memoflow/contracts/goal';const route=useRoute();const router=useRouter();const {t,locale}=useI18n();const {keyResults,getGoalAggregateView}=useGoal();const goalId=String(route.params.goalId??'');const keyResultId=String(route.params.keyResultId??'');const kr=computed(()=>keyResults.value.find(item=>String(item.id)===keyResultId)??null);onMounted(()=>void getGoalAggregateView(goalId));</script>
